import pytest
from hypothesis import example, given, strategies as st

from ledger.intervals.merge import merge_intervals

INTERVALS = st.lists(
    st.tuples(st.integers(-50, 50), st.integers(-50, 50)).map(lambda p: (min(p), max(p))),
    max_size=8,
)


@pytest.mark.invariant("merge_idempotent")
@given(INTERVALS)
@example([(1, 3), (3, 5)])
@example([(5, 7), (1, 6)])
def test_merge_is_idempotent_for_any_order(intervals):
    once = merge_intervals(sorted(intervals))
    assert merge_intervals(once) == once
